// Single-file C++ symbol fixture for the kr232 adapter.
//
// Exercises what a debugger must show for one translation unit: parameters and
// locals with kinds and values, a struct and an array aggregate, a member
// function with `this`, an external-linkage global, a file-scope `static`
// global, and a `static` function. It links against crt0 only (no libc), so the
// image stays small; every value is an int and every initialiser is constant,
// so no global-constructor runtime is involved.
//
// Regenerated by tests/fixtures/kr232/regenerate.ps1 at -O0 and checked by
// CheckFixtureDrift.cmake. Assertions live in
// tests/test_kr232_symbols.cpp and look lines up by token, never by number.

struct Vec {
    int x;
    int y;
};

struct Samples {
    int values[3];
};

int external_total = 5;
static int file_only = 100;
Vec g_vec = {3, 4};
Samples g_samples = {{1, 2, 3}};
int g_values[4] = {10, 20, 30, 40};

class Counter {
public:
    int bump(int delta);
    int stored;
};

static int hidden_add(int n) {
    int adjusted = n + file_only;
    return adjusted;
}

int Counter::bump(int delta) {
    int before = stored;
    int twice = delta + delta;
    stored = before + twice + hidden_add(before);
    return stored;
}

int sum_vec(Vec v) {
    int total = v.x + v.y;
    return total;
}

int loop_sum(int count);

int main(void) {
    Counter counter;
    counter.stored = 7;
    Vec local = {1, 2};
    int pair[2];
    pair[0] = sum_vec(local);
    pair[1] = loop_sum(2);
    int bumped = counter.bump(3);
    return bumped + pair[0] + pair[1] + external_total + g_values[0];
}

int loop_sum(int count) {
    int total = 0;
    int index = 0;
    while (index < count) {
        total += g_values[index];
        index = index + 1;
    }
    return total;
}
